  "ui.agents.refusals.team_nesting": "\u0909\u0938 \u091F\u0940\u092E \u0915\u0947 \u0905\u0902\u0926\u0930 \u092C\u0939\u0941\u0924 \u091C\u093C\u094D\u092F\u093E\u0926\u093E \u0938\u094D\u0924\u0930 \u092C\u0928\u0947\u0902\u0917\u0947 \u092F\u093E \u0935\u0939 \u0916\u093C\u0941\u0926 \u0915\u094B \u0936\u093E\u092E\u093F\u0932 \u0915\u0930\u0947\u0917\u0940\u0964 \u0909\u0938\u0915\u0947 \u0938\u0926\u0938\u094D\u092F \u091C\u093E\u0901\u091A\u0947\u0902\u0964",
  "ui.agents.refusals.class.label.proactive": "\u092A\u0939\u0932 \u0915\u0930\u0928\u0947 \u0935\u093E\u0932\u093E",
  "ui.agents.refusals.class.label.reactive": "\u091C\u0935\u093E\u092C \u0926\u0947\u0928\u0947 \u0935\u093E\u0932\u093E",
  "ui.agents.refusals.class.meaning.proactive": "\u092F\u0939 \u0905\u092A\u0928\u0940 \u0913\u0930 \u0938\u0947 \u0906\u092A\u0915\u094B \u0938\u0902\u0926\u0947\u0936 \u092D\u0947\u091C \u0938\u0915\u0924\u093E \u0939\u0948: \u0915\u0941\u091B \u092D\u0947\u091C\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926 \u091C\u0935\u093E\u092C \u0915\u0947 \u0932\u093F\u090F \u0915\u0941\u091B \u092E\u093F\u0928\u091F \u0930\u0941\u0915\u0924\u093E \u0939\u0948, \u0924\u092F \u0938\u0902\u0916\u094D\u092F\u093E \u092E\u0947\u0902 \u092C\u0922\u093C\u0924\u0947 \u0905\u0902\u0924\u0930\u093E\u0932 \u092A\u0930 \u092B\u093F\u0930 \u092F\u093E\u0926 \u0926\u093F\u0932\u093E\u0924\u093E \u0939\u0948, \u092B\u093F\u0930 \u0906\u092A\u0915\u093E \u0907\u0902\u0924\u091C\u093C\u093E\u0930 \u0915\u0930\u0924\u093E \u0939\u0948 \u2014 \u0914\u0930 \u0905\u092A\u0928\u0947 \u0936\u0947\u0921\u094D\u092F\u0942\u0932 \u092A\u0930 \u092D\u0940 \u091C\u093E\u0917 \u0938\u0915\u0924\u093E \u0939\u0948\u0964",
  "ui.agents.refusals.class.meaning.reactive": "\u092F\u0939 \u0906\u092A\u0915\u0947 \u0932\u093F\u0916\u0928\u0947 \u092A\u0930 \u091C\u0935\u093E\u092C \u0926\u0947\u0924\u093E \u0939\u0948\u0964 \u092F\u0939 \u0906\u092A\u0915\u094B \u092F\u093E\u0926 \u0928\u0939\u0940\u0902 \u0926\u093F\u0932\u093E\u0924\u093E \u0914\u0930 \u0905\u092A\u0928\u0947 \u0936\u0947\u0921\u094D\u092F\u0942\u0932 \u092A\u0930 \u0928\u0939\u0940\u0902 \u091C\u093E\u0917\u0924\u093E\u0964",
  "ui.agents.refusals.class.effect.proactive": "\u0907\u0938\u0947 \u092C\u0902\u0926 \u0915\u0930\u0928\u0947 \u0938\u0947 \u092F\u093E\u0926 \u0926\u093F\u0932\u093E\u0928\u093E \u0914\u0930 \u0936\u0947\u0921\u094D\u092F\u0942\u0932 \u0915\u0940 \u0917\u0908 \u091C\u093E\u0917\u0943\u0924\u093F\u092F\u093E\u0901 \u092C\u0902\u0926 \u0939\u094B \u091C\u093E\u0924\u0940 \u0939\u0948\u0902\u0964 \u0906\u092A\u0915\u0947 \u0932\u093F\u0916\u0928\u0947 \u092A\u0930 \u092F\u0939 \u0905\u092C \u092D\u0940 \u091C\u0935\u093E\u092C \u0926\u0947\u0924\u093E \u0939\u0948\u0964",
  "ui.agents.refusals.class.effect.reactive": "\u0907\u0938\u0947 \u091A\u093E\u0932\u0942 \u0915\u0930\u0928\u0947 \u0938\u0947 \u092F\u0939 \u092A\u0939\u0932\u0947 \u0932\u093F\u0916 \u0938\u0915\u0924\u093E \u0939\u0948: \u0906\u092A\u0915\u0947 \u091C\u0935\u093E\u092C \u0915\u0947 \u0932\u093F\u090F \u0915\u0941\u091B \u092E\u093F\u0928\u091F \u0930\u0941\u0915\u0947\u0917\u093E, \u0924\u092F \u0938\u0902\u0916\u094D\u092F\u093E \u0924\u0915 \u092B\u093F\u0930 \u092F\u093E\u0926 \u0926\u093F\u0932\u093E\u090F\u0917\u093E \u0914\u0930 \u0905\u092A\u0928\u0947 \u0936\u0947\u0921\u094D\u092F\u0942\u0932 \u092A\u0930 \u091C\u093E\u0917 \u0938\u0915\u0924\u093E \u0939\u0948\u0964 \u0906\u092A\u0915\u0947 \u0932\u093F\u0916\u0928\u0947 \u092A\u0930 \u092F\u0939 \u0905\u092C \u092D\u0940 \u091C\u0935\u093E\u092C \u0926\u0947\u0924\u093E \u0939\u0948\u0964",
  "ui.agents.refusals.class.install_disclosure": "\u092F\u0939 \u0910\u092A \u0915\u0947 \u0938\u093E\u0925 \u0906\u0924\u093E \u0939\u0948 \u0914\u0930 \u0905\u092D\u0940 \u0907\u0938\u0915\u0940 \u0905\u092A\u0928\u0940 \u0915\u0949\u092A\u0940 \u0928\u0939\u0940\u0902 \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u0938\u094D\u0935\u093F\u091A \u092C\u0926\u0932\u0928\u0947 \u0938\u0947 \u092A\u0939\u0932\u0947 \u092F\u0939 \u0907\u0902\u0938\u094D\u091F\u0949\u0932 \u0939\u094B\u0924\u093E \u0939\u0948 \u2014 \u0935\u0939\u0940 \u090F\u091C\u0947\u0902\u091F \u0914\u0930 \u0935\u0939\u0940 \u0928\u093F\u0930\u094D\u0926\u0947\u0936, \u091C\u093F\u0928\u094D\u0939\u0947\u0902 \u0905\u092C \u092C\u0926\u0932\u093E \u091C\u093E \u0938\u0915\u0924\u093E \u0939\u0948 \u2014 \u0914\u0930 \u092B\u093F\u0930 \u0907\u0938\u0915\u0940 \u0936\u094D\u0930\u0947\u0923\u0940 \u0924\u092F \u0939\u094B\u0924\u0940 \u0939\u0948\u0964",
  "ui.agents.refusals.class.error.no_reason": "\u092C\u0948\u0915\u090F\u0902\u0921 \u0928\u0947 \u0907\u0938\u0915\u0940 \u0915\u094B\u0908 \u0935\u091C\u0939 \u0928\u0939\u0940\u0902 \u092D\u0947\u091C\u0940\u0964 \u0938\u094D\u0935\u093F\u091A \u092B\u093F\u0930 \u092C\u0926\u0932\u0915\u0930 \u0926\u0947\u0916\u0947\u0902\u0964",
  "ui.agents.refusals.class.error.install_landed": "{reason} \u0907\u0902\u0938\u094D\u091F\u0949\u0932 \u0939\u094B \u0917\u092F\u093E \u0925\u093E, \u0907\u0938\u0932\u093F\u090F \u0905\u092C \u090F\u091C\u0947\u0902\u091F \u092E\u0947\u0902 \u092C\u0926\u0932\u093E\u0935 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964"
