  "ui.console.capacity.full": " \xB7 \u0938\u0940\u092E\u093E \u092A\u0942\u0930\u0940",
  "ui.console.capacity.help": "\u092F\u0947 \u0917\u093F\u0928\u0924\u093F\u092F\u093E\u0901 \u092A\u0942\u0930\u0947 \u0910\u092A \u0915\u0940 \u0938\u092D\u0940 \u092C\u093E\u0924\u091A\u0940\u0924\u094B\u0902 \u0915\u0947 \u0932\u093F\u090F \u0939\u0948\u0902\u0964 \u0930\u0916\u0947 \u0917\u090F \u0907\u0924\u093F\u0939\u093E\u0938 \u0915\u0947 \u0932\u093F\u090F \u092A\u094D\u0930\u094B\u0938\u0947\u0938 \u0938\u094D\u0932\u0949\u091F \u0928\u0939\u0940\u0902 \u0932\u0917\u0924\u093E\u0964",
  "ui.console.capacity.resources": "\u092A\u094D\u0930\u092C\u0902\u0927\u093F\u0924 \u0938\u094D\u091F\u094B\u0930\u0947\u091C \u0915\u093E \u0905\u0928\u0941\u092E\u093E\u0928: {memory, number, ::group-off} MiB\u0964 \u0932\u0949\u0917: {logs, number, ::group-off} MiB\u0964 \u0932\u0902\u092C\u093F\u0924 \u0906\u0909\u091F\u092A\u0941\u091F: {pending, number, ::group-off} MiB\u0964 \u091F\u0930\u094D\u092E\u093F\u0928\u0932 \u0938\u0947\u0932: {cells, number, ::group-off}\u0964 \u0938\u0941\u0930\u0915\u094D\u0937\u093F\u0924 \u0930\u0916\u0947 \u0917\u090F \u091F\u0930\u094D\u092E\u093F\u0928\u0932: {protected, number, ::group-off}\u0964 \u0907\u0938\u092E\u0947\u0902 \u091A\u093E\u0907\u0932\u094D\u0921 \u092A\u094D\u0930\u094B\u0938\u0947\u0938 \u0915\u0940 \u092E\u0947\u092E\u094B\u0930\u0940 \u0936\u093E\u092E\u093F\u0932 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964",
  "ui.console.cleanup.label": "\u090F\u091C\u0947\u0902\u091F \u0915\u0947 \u0938\u092E\u093E\u092A\u094D\u0924 \u091F\u0930\u094D\u092E\u093F\u0928\u0932 \u0939\u091F\u093E\u090F\u0901",
  "ui.console.cleanup.help": "\u0907\u0938 \u092C\u093E\u0924\u091A\u0940\u0924 \u092E\u0947\u0902 \u090F\u091C\u0947\u0902\u091F \u0915\u0947 \u0938\u092E\u093E\u092A\u094D\u0924 \u091F\u0930\u094D\u092E\u093F\u0928\u0932 \u0939\u091F\u093E\u0924\u093E \u0939\u0948\u0964 \u091C\u093F\u0928 \u0938\u092E\u093E\u092A\u094D\u0924 \u091F\u0930\u094D\u092E\u093F\u0928\u0932\u094B\u0902 \u0915\u094B \u0930\u0916\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u090F\u091C\u0947\u0902\u091F \u0928\u0947 \u0915\u0939\u093E \u0925\u093E, \u0935\u0947 \u0921\u093F\u0938\u094D\u0915 \u092A\u0930 \u092C\u0928\u0947 \u0930\u0939\u0924\u0947 \u0939\u0948\u0902; \u092C\u093E\u0915\u0940 \u092C\u0902\u0926 \u0915\u0930 \u0926\u093F\u090F \u091C\u093E\u0924\u0947 \u0939\u0948\u0902 \u0914\u0930 \u0909\u0928\u0915\u093E \u0906\u0909\u091F\u092A\u0941\u091F \u0928\u0939\u0940\u0902 \u0930\u0916\u093E \u091C\u093E\u0924\u093E\u0964 \u0906\u092A\u0915\u0947 \u0916\u094B\u0932\u0947 \u0939\u0941\u090F \u0914\u0930 \u0907\u0938\u094D\u0924\u0947\u092E\u093E\u0932 \u092E\u0947\u0902 \u092E\u094C\u091C\u0942\u0926 \u091F\u0930\u094D\u092E\u093F\u0928\u0932 \u0928\u0939\u0940\u0902 \u092C\u0926\u0932\u0947 \u091C\u093E\u0924\u0947\u0964",
  "ui.console.cleanup.result": "{released, plural, one {\u090F\u091C\u0947\u0902\u091F \u0915\u093E {released, number, ::group-off} \u0938\u092E\u093E\u092A\u094D\u0924 \u091F\u0930\u094D\u092E\u093F\u0928\u0932 \u0939\u091F\u093E\u092F\u093E \u0917\u092F\u093E\u0964} other {\u090F\u091C\u0947\u0902\u091F \u0915\u0947 {released, number, ::group-off} \u0938\u092E\u093E\u092A\u094D\u0924 \u091F\u0930\u094D\u092E\u093F\u0928\u0932 \u0939\u091F\u093E\u090F \u0917\u090F\u0964}} {protected, plural, =0 {} one {{protected, number, ::group-off} \u0905\u092D\u0940 \u0907\u0938\u094D\u0924\u0947\u092E\u093E\u0932 \u092E\u0947\u0902 \u0939\u0948 \u0914\u0930 \u0916\u0941\u0932\u093E \u091B\u094B\u0921\u093C\u093E \u0917\u092F\u093E\u0964} other {{protected, number, ::group-off} \u0905\u092D\u0940 \u0907\u0938\u094D\u0924\u0947\u092E\u093E\u0932 \u092E\u0947\u0902 \u0939\u0948\u0902 \u0914\u0930 \u0916\u0941\u0932\u0947 \u091B\u094B\u0921\u093C\u0947 \u0917\u090F\u0964}}",
  "ui.console.cleanup.result_none": "\u0939\u091F\u093E\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0915\u0941\u091B \u0928\u0939\u0940\u0902 \u2014 \u0907\u0938 \u092C\u093E\u0924\u091A\u0940\u0924 \u092E\u0947\u0902 \u090F\u091C\u0947\u0902\u091F \u0915\u093E \u0915\u094B\u0908 \u0938\u092E\u093E\u092A\u094D\u0924 \u091F\u0930\u094D\u092E\u093F\u0928\u0932 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964",
  "ui.console.dismiss_history": "\u091F\u0930\u094D\u092E\u093F\u0928\u0932 \u0939\u091F\u093E\u090F\u0901 \u0914\u0930 \u0930\u0916\u093E \u0917\u092F\u093E \u0906\u0909\u091F\u092A\u0941\u091F \u092E\u093F\u091F\u093E\u090F\u0901",
  "ui.console.dismiss.body": "\u0907\u0938 \u091F\u0930\u094D\u092E\u093F\u0928\u0932 \u0915\u094B \u0939\u091F\u093E\u0928\u0947 \u0938\u0947 \u0909\u0938\u0915\u093E \u0930\u0916\u093E \u0917\u092F\u093E \u0906\u0909\u091F\u092A\u0941\u091F \u0921\u093F\u0938\u094D\u0915 \u0938\u0947 \u092E\u093F\u091F \u091C\u093E\u0924\u093E \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u0910\u092A \u0926\u094B\u092C\u093E\u0930\u093E \u0936\u0941\u0930\u0942 \u0915\u0930\u0928\u0947 \u092A\u0930 \u0935\u0939 \u092C\u0939\u093E\u0932 \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u0947\u0917\u093E\u0964",
  "ui.console.dismiss.title": "\u092F\u0939 \u091F\u0930\u094D\u092E\u093F\u0928\u0932 \u0939\u091F\u093E\u090F\u0901?",
  "ui.console.dismiss.confirm": "\u091F\u0930\u094D\u092E\u093F\u0928\u0932 \u0939\u091F\u093E\u090F\u0901",
  "ui.console.close.body": "\u092F\u0939 \u092F\u0939\u093E\u0901 \u091A\u0932 \u0930\u0939\u0947 \u092A\u094D\u0930\u094B\u0917\u094D\u0930\u093E\u092E \u0915\u094B \u092C\u0902\u0926 \u0915\u0930 \u0926\u0947\u0924\u093E \u0939\u0948 \u0914\u0930 \u0909\u0938\u0915\u093E \u091F\u0948\u092C \u0939\u091F\u093E \u0926\u0947\u0924\u093E \u0939\u0948\u0964",
  "ui.console.close.busy": "\u092C\u0902\u0926 \u0939\u094B \u0930\u0939\u093E \u0939\u0948\u2026",
