  "ui.console.close.kept": "\u0909\u0938\u0915\u093E \u0906\u0909\u091F\u092A\u0941\u091F \u0930\u0916\u093E \u091C\u093E\u0924\u093E \u0939\u0948\u0964",
  "ui.console.close.title": "\u092F\u0939 \u091F\u0930\u094D\u092E\u093F\u0928\u0932 \u092C\u0902\u0926 \u0915\u0930\u0947\u0902?",
  "ui.console.create_failed.detail": "\u0915\u0902\u0938\u094B\u0932 \u0939\u094B\u0938\u094D\u091F \u091A\u0932 \u0930\u0939\u093E \u0939\u0948, \u0932\u0947\u0915\u093F\u0928 \u0909\u0938\u0928\u0947 \u0907\u0938 \u092C\u093E\u0924\u091A\u0940\u0924 \u0915\u0947 \u0932\u093F\u090F \u092A\u094D\u0930\u094B\u0917\u094D\u0930\u093E\u092E \u0936\u0941\u0930\u0942 \u0915\u0930\u0928\u0947 \u0938\u0947 \u0907\u0928\u0915\u093E\u0930 \u0915\u093F\u092F\u093E \u2014 \u0907\u0938\u0932\u093F\u090F \u0938\u093F\u0930\u094D\u092B\u093C \u092F\u0939 \u0915\u094B\u0936\u093F\u0936 \u0935\u093F\u092B\u0932 \u0939\u0941\u0908 \u0939\u0948, \u0915\u0902\u0938\u094B\u0932 \u092C\u0902\u0926 \u0928\u0939\u0940\u0902 \u0915\u093F\u092F\u093E \u0917\u092F\u093E \u0939\u0948\u0964 \u092A\u0939\u0932\u0947 \u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0947\u0902; \u0905\u0917\u0930 \u092C\u093E\u0930-\u092C\u093E\u0930 \u0935\u093F\u092B\u0932 \u0939\u094B, \u0924\u094B \u0928\u0940\u091A\u0947 \u0939\u094B\u0938\u094D\u091F \u0915\u093E \u092C\u0924\u093E\u092F\u093E \u0915\u093E\u0930\u0923 \u0926\u0947\u0916\u0947\u0902\u0964",
  "ui.console.create_failed.retry": "\u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0947\u0902",
  "ui.console.create_failed.title": "\u0907\u0938 \u0938\u0924\u094D\u0930 \u092E\u0947\u0902 \u0915\u0902\u0938\u094B\u0932 \u0936\u0941\u0930\u0942 \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u093E",
  "ui.console.empty.detail": "\u0915\u0902\u0938\u094B\u0932 \u0907\u0938 \u092C\u093E\u0924\u091A\u0940\u0924 \u0915\u0947 \u092B\u093C\u094B\u0932\u094D\u0921\u0930 \u092E\u0947\u0902 \u092A\u094D\u0930\u094B\u0917\u094D\u0930\u093E\u092E \u091A\u0932\u093E\u0924\u093E \u0939\u0948 \u0914\u0930 \u0909\u0938\u0915\u093E \u0906\u0909\u091F\u092A\u0941\u091F \u0930\u0916\u0924\u093E \u0939\u0948, \u091A\u093E\u0939\u0947 \u092F\u0939 \u092A\u0948\u0928\u0932 \u0916\u0941\u0932\u093E \u0939\u094B \u092F\u093E \u0928\u0939\u0940\u0902\u0964",
  "ui.console.empty.title": "\u0907\u0938 \u0938\u0924\u094D\u0930 \u092E\u0947\u0902 \u0915\u094B\u0908 \u0915\u0902\u0938\u094B\u0932 \u0928\u0939\u0940\u0902 \u0939\u0948",
  "ui.console.ended.app_quit": "\u0910\u092A \u092C\u0902\u0926 \u0939\u094B\u0928\u0947 \u092A\u0930 \u0907\u0938\u0947 \u092C\u0902\u0926 \u0915\u093F\u092F\u093E \u0917\u092F\u093E",
