  "ui.settings.appearance.window_glass.material_acrylic": "Acrylic",
  "ui.settings.appearance.window_glass.material_tabbed": "Tabbed",
  "ui.settings.appearance.window_glass.intensity_start": "\u0927\u0941\u0902\u0927\u0932\u093E",
  "ui.settings.appearance.window_glass.intensity_end": "\u092A\u093E\u0930\u0926\u0930\u094D\u0936\u0940",
  "ui.settings.appearance.window_glass.intensity_value": "\u092A\u093E\u0930\u0926\u0930\u094D\u0936\u093F\u0924\u093E \u0915\u0940 \u0913\u0930 {value}%",
  "ui.settings.appearance.window_glass.unsupported_windows_unverified": "Windows \u092A\u0930 \u092A\u093E\u0930\u092D\u093E\u0938\u0940 \u0935\u093F\u0902\u0921\u094B \u0905\u092D\u0940 \u0928\u0939\u0940\u0902 \u0926\u0940 \u091C\u093E\u0924\u0940: Mica \u0914\u0930 Acrylic \u092C\u0928\u093E\u090F \u0917\u090F \u0939\u0948\u0902, \u0932\u0947\u0915\u093F\u0928 \u0909\u0928\u094D\u0939\u0947\u0902 \u0905\u0938\u0932\u0940 Windows \u092E\u0936\u0940\u0928 \u092A\u0930 \u0928\u0939\u0940\u0902 \u092A\u0930\u0916\u093E \u0917\u092F\u093E \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u0909\u0938 \u091C\u093E\u0901\u091A \u0915\u0947 \u092A\u0942\u0930\u093E \u0939\u094B\u0928\u0947 \u0924\u0915 \u0915\u0902\u091F\u094D\u0930\u094B\u0932 \u092C\u0902\u0926 \u0930\u0939\u0947\u0917\u093E\u0964",
  "ui.settings.appearance.window_glass.unsupported_gpu": "\u092A\u093E\u0930\u092D\u093E\u0938\u0940 \u0935\u093F\u0902\u0921\u094B \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948, \u0915\u094D\u092F\u094B\u0902\u0915\u093F GPU \u0905\u092D\u0940 \u0909\u0938\u0947 \u092C\u0928\u093E\u0915\u0930 \u0928\u0939\u0940\u0902 \u0926\u093F\u0916\u093E \u0938\u0915\u0924\u093E: \u0915\u0902\u092A\u094B\u091C\u093C\u093F\u091F\u093F\u0902\u0917 \u092F\u093E \u0930\u0948\u0938\u094D\u091F\u0930\u093E\u0907\u091C\u093C\u0947\u0936\u0928 \u092C\u0902\u0926 \u0939\u0948 \u092F\u093E \u0938\u0949\u092B\u093C\u094D\u091F\u0935\u0947\u092F\u0930 \u092E\u0947\u0902 \u091A\u0932 \u0930\u0939\u093E \u0939\u0948\u0964 \u0921\u094D\u0930\u093E\u0907\u0935\u0930 \u0905\u092A\u0921\u0947\u091F \u0915\u0930\u0928\u0947 \u092F\u093E \u0930\u093F\u092E\u094B\u091F \u0938\u0924\u094D\u0930 \u0938\u0947 \u092C\u093E\u0939\u0930 \u0928\u093F\u0915\u0932\u0928\u0947 \u092A\u0930 \u092C\u093F\u0928\u093E \u0926\u094B\u092C\u093E\u0930\u093E \u0936\u0941\u0930\u0942 \u0915\u093F\u090F \u0915\u0902\u091F\u094D\u0930\u094B\u0932 \u0935\u093E\u092A\u0938 \u0906 \u0938\u0915\u0924\u093E \u0939\u0948\u0964",
  "ui.settings.appearance.window_glass.unsupported_acceleration": "\u092A\u093E\u0930\u092D\u093E\u0938\u0940 \u0935\u093F\u0902\u0921\u094B \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948, \u0915\u094D\u092F\u094B\u0902\u0915\u093F \u0907\u0938 \u092C\u093E\u0930 \u0939\u093E\u0930\u094D\u0921\u0935\u0947\u092F\u0930 \u090F\u0915\u094D\u0938\u0947\u0932\u0930\u0947\u0936\u0928 \u092C\u0902\u0926 \u0939\u0948 (--disable-gpu \u092F\u093E \u0915\u094D\u0930\u0948\u0936 \u0915\u0947 \u092C\u093E\u0926 \u0935\u0948\u0915\u0932\u094D\u092A\u093F\u0915 \u092E\u094B\u0921)\u0964 \u0907\u0938\u0947 \u0907\u0938\u094D\u0924\u0947\u092E\u093E\u0932 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u090F\u0915\u094D\u0938\u0947\u0932\u0930\u0947\u0936\u0928 \u091A\u093E\u0932\u0942 \u0915\u0930\u0915\u0947 \u0926\u094B\u092C\u093E\u0930\u093E \u0936\u0941\u0930\u0942 \u0915\u0930\u0947\u0902\u0964",
  "ui.settings.appearance.window_glass.unsupported_backdrop_filter": "\u092A\u093E\u0930\u092D\u093E\u0938\u0940 \u0935\u093F\u0902\u0921\u094B \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948, \u0915\u094D\u092F\u094B\u0902\u0915\u093F \u092F\u0939 \u0930\u0947\u0902\u0921\u0930\u0930 \u092A\u0940\u091B\u0947 \u0915\u093E \u0926\u0943\u0936\u094D\u092F \u0927\u0941\u0902\u0927\u0932\u093E \u0928\u0939\u0940\u0902 \u0915\u0930 \u0938\u0915\u0924\u093E\u0964"
