  "ui.settings.language.general.pending": "\u092D\u093E\u0937\u093E \u0938\u0939\u0947\u091C\u0940 \u091C\u093E \u0930\u0939\u0940 \u0939\u0948\u2026",
  "ui.settings.language.general.readback_error": "\u092C\u0926\u0932\u093E\u0935 \u0938\u0939\u0947\u091C\u0947 \u091C\u093E\u0928\u0947 \u0915\u0940 \u092A\u0941\u0937\u094D\u091F\u093F \u0939\u0941\u0908, \u0932\u0947\u0915\u093F\u0928 \u092E\u094C\u091C\u0942\u0926\u093E \u0938\u0947\u091F\u093F\u0902\u0917 \u091C\u093E\u0901\u091A\u0940 \u0928\u0939\u0940\u0902 \u091C\u093E \u0938\u0915\u0940\u0964 \u0926\u094B\u092C\u093E\u0930\u093E \u092C\u0926\u0932\u0928\u0947 \u0938\u0947 \u092A\u0939\u0932\u0947 \u092B\u093F\u0930 \u0915\u0928\u0947\u0915\u094D\u091F \u0915\u0930\u0947\u0902 \u092F\u093E \u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0947\u0902\u0964",
  "ui.settings.language.general.saved": "\u092D\u093E\u0937\u093E \u0938\u0939\u0947\u091C\u0940 \u0917\u0908\u0964",
  "ui.settings.language.general.system": "\u0938\u093F\u0938\u094D\u091F\u092E \u0915\u0940 \u092D\u093E\u0937\u093E \u0932\u0947\u0902",
  "ui.settings.language.general.unavailable_choice": "\u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902",
  "ui.settings.language.general.write_error": "\u092D\u093E\u0937\u093E \u0938\u0939\u0947\u091C\u0940 \u0928\u0939\u0940\u0902 \u0917\u0908\u0964 \u0906\u092A\u0915\u0940 \u092A\u093F\u091B\u0932\u0940 \u0938\u0947\u091F\u093F\u0902\u0917 \u0928\u0939\u0940\u0902 \u092C\u0926\u0932\u0940 \u0939\u0948\u0964 {message}",
  "ui.settings.language.palette_action": "\u0907\u0902\u091F\u0930\u092B\u093C\u0947\u0938 \u0915\u0940 \u092D\u093E\u0937\u093E \u092C\u0926\u0932\u0947\u0902",
  "ui.settings.page.title": "\u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938",
  "ui.settings.profile.description_anonymous": "\u0910\u092A \u092E\u0947\u0902 \u0926\u093F\u0916\u093E\u0908 \u091C\u093E\u0928\u0947 \u0935\u093E\u0932\u0940 \u0906\u092A\u0915\u0940 \u092A\u094D\u0930\u094B\u092B\u093C\u093E\u0907\u0932 \u0915\u0940 \u091C\u093E\u0928\u0915\u093E\u0930\u0940\u0964 \u092F\u0939 \u091C\u093E\u0928\u0915\u093E\u0930\u0940 \u090F\u091C\u0947\u0902\u091F\u094B\u0902 \u0915\u094B \u0928\u0939\u0940\u0902 \u0926\u0940 \u091C\u093E\u0924\u0940\u0964",
  "ui.settings.profile.description_authenticated": "\u0910\u092A \u092E\u0947\u0902 \u0926\u093F\u0916\u093E\u0908 \u091C\u093E\u0928\u0947 \u0935\u093E\u0932\u0940 \u0906\u092A\u0915\u0940 \u092A\u094D\u0930\u094B\u092B\u093C\u093E\u0907\u0932 \u0915\u0940 \u091C\u093E\u0928\u0915\u093E\u0930\u0940\u0964 \u092F\u0939 \u091C\u093E\u0928\u0915\u093E\u0930\u0940 \u090F\u091C\u0947\u0902\u091F\u094B\u0902 \u0915\u094B \u0928\u0939\u0940\u0902 \u0926\u0940 \u091C\u093E\u0924\u0940\u0964 \u092F\u0947 \u0935\u093F\u0935\u0930\u0923 \u0906\u092A\u0915\u0947 Radient \u0916\u093E\u0924\u0947 \u0938\u0947 \u092E\u093F\u0932\u0924\u0947 \u0939\u0948\u0902\u0964",
  "ui.settings.profile.display_name.label": "\u0926\u093F\u0916\u093E\u092F\u093E \u091C\u093E\u0928\u0947 \u0935\u093E\u0932\u093E \u0928\u093E\u092E",
  "ui.settings.profile.display_name.placeholder": "\u0905\u092A\u0928\u093E \u0928\u093E\u092E \u0926\u0930\u094D\u091C \u0915\u0930\u0947\u0902...",
  "ui.settings.profile.email.label": "\u0908\u092E\u0947\u0932 \u092A\u0924\u093E",
  "ui.settings.profile.email.placeholder": "\u0905\u092A\u0928\u093E \u0908\u092E\u0947\u0932 \u0926\u0930\u094D\u091C \u0915\u0930\u0947\u0902...",
  "ui.settings.profile.title": "\u0909\u092A\u092F\u094B\u0917\u0915\u0930\u094D\u0924\u093E \u092A\u094D\u0930\u094B\u092B\u093C\u093E\u0907\u0932",
  "ui.settings.section.interface_language.help": "\u0907\u0902\u091F\u0930\u092B\u093C\u0947\u0938 \u0915\u0940 \u092D\u093E\u0937\u093E \u0915\u0940 \u092F\u0939\u0940 \u0938\u0947\u091F\u093F\u0902\u0917 \u091F\u0930\u094D\u092E\u093F\u0928\u0932 \u092A\u0930 \u092D\u0940 \u0932\u093E\u0917\u0942 \u0939\u094B\u0924\u0940 \u0939\u0948\u0964 auto \u0906\u092A\u0915\u0947 \u0911\u092A\u0930\u0947\u091F\u093F\u0902\u0917 \u0938\u093F\u0938\u094D\u091F\u092E \u0915\u0940 \u092D\u093E\u0937\u093E \u0932\u0947\u0924\u093E \u0939\u0948; \u0935\u0939 \u0928 \u092E\u093F\u0932\u0928\u0947 \u092A\u0930 \u0905\u0902\u0917\u094D\u0930\u0947\u091C\u093C\u0940\u0964",
  "ui.settings.section.interface_language.label": "\u0907\u0902\u091F\u0930\u092B\u093C\u0947\u0938 \u0915\u0940 \u092D\u093E\u0937\u093E",
  "ui.settings.tour.action": "\u0910\u092A \u0915\u093E \u092A\u0930\u093F\u091A\u092F \u0926\u0947\u0916\u0947\u0902",
  "ui.settings.tour.description": "\u0910\u092A \u0915\u093E \u0936\u0941\u0930\u0941\u0906\u0924\u0940 \u092A\u0930\u093F\u091A\u092F \u091B\u0942\u091F \u0917\u092F\u093E \u0925\u093E \u092F\u093E \u092B\u093F\u0930 \u0938\u0947 \u0926\u0947\u0916\u0928\u093E \u091A\u093E\u0939\u0924\u0947 \u0939\u0948\u0902? \u092F\u0939\u093E\u0901 \u0938\u0947 \u0926\u094B\u092C\u093E\u0930\u093E \u0936\u0941\u0930\u0942 \u0915\u0930\u0947\u0902\u0964",
  "ui.settings.tour.title": "\u0910\u092A \u0915\u093E \u092A\u0930\u093F\u091A\u092F",
  "ui.settings.profile.account_checking": "\u0906\u092A\u0915\u093E Radient \u0916\u093E\u0924\u093E \u091C\u093E\u0901\u091A\u093E \u091C\u093E \u0930\u0939\u093E \u0939\u0948\u2026",
  "ui.settings.profile.account_read_failed_retry": "\u0906\u092A\u0915\u0947 Radient \u0916\u093E\u0924\u0947 \u0915\u0940 \u091C\u093E\u0928\u0915\u093E\u0930\u0940 \u0928\u0939\u0940\u0902 \u092A\u0922\u093C\u0940 \u091C\u093E \u0938\u0915\u0940, \u0907\u0938\u0932\u093F\u090F \u0928\u0940\u091A\u0947 \u0926\u093F\u090F \u0928\u093E\u092E \u0914\u0930 \u0908\u092E\u0947\u0932 \u0915\u0947\u0935\u0932 \u0928\u092E\u0942\u0928\u0947 \u0939\u0948\u0902, \u0906\u092A\u0915\u0947 \u0916\u093E\u0924\u0947 \u0915\u0940 \u091C\u093E\u0928\u0915\u093E\u0930\u0940 \u0928\u0939\u0940\u0902\u0964 \u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0947\u0902\u0964",
  "ui.settings.profile.account_read_failed_refused": "\u0906\u092A\u0915\u0947 Radient \u0916\u093E\u0924\u0947 \u0915\u0940 \u091C\u093E\u0928\u0915\u093E\u0930\u0940 \u0928\u0939\u0940\u0902 \u092A\u0922\u093C\u0940 \u091C\u093E \u0938\u0915\u0940, \u0907\u0938\u0932\u093F\u090F \u0928\u0940\u091A\u0947 \u0926\u093F\u090F \u0928\u093E\u092E \u0914\u0930 \u0908\u092E\u0947\u0932 \u0915\u0947\u0935\u0932 \u0928\u092E\u0942\u0928\u0947 \u0939\u0948\u0902, \u0906\u092A\u0915\u0947 \u0916\u093E\u0924\u0947 \u0915\u0940 \u091C\u093E\u0928\u0915\u093E\u0930\u0940 \u0928\u0939\u0940\u0902\u0964 \u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0947\u0902 \u092F\u093E Radient \u092E\u0947\u0902 \u0926\u094B\u092C\u093E\u0930\u093E \u0938\u093E\u0907\u0928 \u0907\u0928 \u0915\u0930\u0947\u0902\u0964",
  "ui.settings.profile.retry": "\u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0947\u0902",
  "ui.settings.profile.retrying": "\u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0939\u094B \u0930\u0939\u0940 \u0939\u0948"
