  "ui.agentMessages.settings.consent.renew": "\u0421\u043E\u0433\u043B\u0430\u0441\u0438\u0435 \u043D\u0443\u0436\u043D\u043E \u043E\u0431\u043D\u043E\u0432\u0438\u0442\u044C. \u041F\u0440\u043E\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0430\u043A\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0439 \u0442\u0435\u043A\u0441\u0442 \u0438 \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u0435 \u0441\u043D\u043E\u0432\u0430.",
  "ui.agentMessages.settings.consent.unavailable": "\u0421\u043E\u0433\u043B\u0430\u0441\u0438\u0435 \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E. \u0421\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F \u0430\u0433\u0435\u043D\u0442\u043E\u0432 \u043D\u0435 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u044B.",
  "ui.agentMessages.settings.consent.changed": "\u041F\u0440\u043E\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0430\u043A\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0439 \u0442\u0435\u043A\u0441\u0442 \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u044F \u043D\u0438\u0436\u0435 \u0438 \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u0435 \u0441\u043D\u043E\u0432\u0430.",
  "ui.agentMessages.settings.allowlist.title": "\u0414\u043E\u0441\u0442\u0443\u043F",
  "ui.agentMessages.settings.allowlist.description": "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435, \u043A\u0442\u043E \u043C\u043E\u0436\u0435\u0442 \u043F\u0438\u0441\u0430\u0442\u044C \u0432\u0430\u043C \u0438 \u043A\u043E\u043C\u0443 \u043C\u043E\u0436\u0435\u0442\u0435 \u043F\u0438\u0441\u0430\u0442\u044C \u0432\u044B.",
