  "ui.agentMessages.settings.allowlist.receive": "\u041A\u0442\u043E \u043C\u043E\u0436\u0435\u0442 \u043F\u0438\u0441\u0430\u0442\u044C \u0432\u0430\u043C",
  "ui.agentMessages.settings.allowlist.anyone": "\u0412\u0441\u0435 \u0432 \u043C\u043E\u0435\u0439 \u043E\u0440\u0433\u0430\u043D\u0438\u0437\u0430\u0446\u0438\u0438",
