  "ui.agentMessages.settings.allowlist.allowed_empty": "\u041F\u043E\u043A\u0430 \u043D\u0435\u0442 \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043D\u043D\u044B\u0445 \u0430\u0433\u0435\u043D\u0442\u043E\u0432 \u0438\u043B\u0438 \u043B\u044E\u0434\u0435\u0439.",
