  "ui.console.capacity.summary": "\u0410\u043A\u0442\u0438\u0432\u043D\u044B\u0445 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u043E\u0432 \u0432 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0438: {live, number, ::group-off} \u0438\u0437 {limit, number, ::group-off}",
