  "ui.console.pane.surfaces": "\u0422\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u044B \u043A\u043E\u043D\u0441\u043E\u043B\u0438",
  "ui.console.secure": "\u0417\u0430\u0449\u0438\u0449\u0451\u043D\u043D\u044B\u0439 \u0432\u0432\u043E\u0434 \u0432\u043A\u043B\u044E\u0447\u0451\u043D: \u0432\u0432\u0435\u0434\u0451\u043D\u043D\u044B\u0439 \u0437\u0434\u0435\u0441\u044C \u0442\u0435\u043A\u0441\u0442 \u043D\u0435 \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442\u0441\u044F.",
  "ui.console.unavailable.disabled.detail": "\u0412 \u043E\u043A\u0440\u0443\u0436\u0435\u043D\u0438\u0438 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F LOCAL_OPERATOR_UI_CONSOLE_HOST \u0437\u0430\u0434\u0430\u043D\u043E \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 0, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u044B \u043D\u0435 \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u044E\u0442\u0441\u044F \u0438 \u0441\u043E\u0437\u0434\u0430\u0442\u044C \u043D\u043E\u0432\u044B\u0439 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B \u043D\u0435\u043B\u044C\u0437\u044F. \u0423\u0434\u0430\u043B\u0438\u0442\u0435 \u044D\u0442\u0443 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0443, \u0447\u0442\u043E\u0431\u044B \u0441\u043D\u043E\u0432\u0430 \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u043A\u043E\u043D\u0441\u043E\u043B\u044C.",
  "ui.console.unavailable.disabled.title": "\u041A\u043E\u043D\u0441\u043E\u043B\u044C \u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u0430 \u0432 \u044D\u0442\u043E\u043C \u0437\u0430\u043F\u0443\u0441\u043A\u0435",
