  "ui.providers.phone.address_label": "\u0410\u0434\u0440\u0435\u0441 \u0434\u043B\u044F \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u0441 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0430",
