  "ui.providers.phone.outcome.billing_activated_status": "\u041E\u043F\u043B\u0430\u0442\u0430: \u0430\u043A\u0442\u0438\u0432\u0430\u0446\u0438\u044F \u043F\u043E\u0434\u043F\u0438\u0441\u043A\u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0430; \u044D\u0442\u043E \u043D\u0435 \u043E\u0442\u043C\u0435\u043D\u0435\u043D\u043E.",
  "ui.providers.phone.outcome.billing_already_active": "\u041E\u043F\u043B\u0430\u0442\u0430: \u043F\u043E\u0434\u043F\u0438\u0441\u043A\u0430 \u0443\u0436\u0435 \u0431\u044B\u043B\u0430 \u0430\u043A\u0442\u0438\u0432\u043D\u0430.",
  "ui.providers.phone.outcome.billing_not_activated": "\u041E\u043F\u043B\u0430\u0442\u0430: \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u043F\u043E\u0434\u043F\u0438\u0441\u043A\u0443 \u0435\u0449\u0451 \u043D\u0443\u0436\u043D\u043E \u0430\u043A\u0442\u0438\u0432\u0438\u0440\u043E\u0432\u0430\u0442\u044C.",
  "ui.providers.phone.outcome.billing_unconfirmed": "\u041E\u043F\u043B\u0430\u0442\u0430: \u0430\u043A\u0442\u0438\u0432\u0430\u0446\u0438\u044F \u0437\u0430\u043F\u0440\u043E\u0448\u0435\u043D\u0430, \u043D\u043E \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u043D\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043D. \u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u0443\u0447\u0451\u0442\u043D\u0443\u044E \u0437\u0430\u043F\u0438\u0441\u044C \u043F\u0435\u0440\u0435\u0434 \u043F\u043E\u0432\u0442\u043E\u0440\u043E\u043C; \u043D\u0435 \u0441\u0447\u0438\u0442\u0430\u0439\u0442\u0435, \u0447\u0442\u043E \u043E\u0442\u043A\u0430\u0442 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D.",
