var ui_settings_appearance_window_glass_default5 = {
  "ui.settings.appearance.window_glass.coverage_description": "\u041A\u0430\u043A\u0438\u0435 \u0447\u0430\u0441\u0442\u0438 \u043E\u043A\u043D\u0430 \u0441\u0442\u0430\u043D\u043E\u0432\u044F\u0442\u0441\u044F \u043F\u043E\u043B\u0443\u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u044B\u043C\u0438. \xAB\u0422\u043E\u043B\u044C\u043A\u043E \u0431\u043E\u043A\u043E\u0432\u044B\u0435 \u043F\u0430\u043D\u0435\u043B\u0438\xBB \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440 \u0438 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u043D\u0435\u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u044B\u043C\u0438. \xAB\u0412\u0441\u0451 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435\xBB \u0442\u0430\u043A\u0436\u0435 \u043E\u0445\u0432\u0430\u0442\u044B\u0432\u0430\u0435\u0442 \u0438\u0445 \u0438 \u0431\u043E\u043A\u043E\u0432\u044B\u0435 \u043F\u0430\u043D\u0435\u043B\u0438; \u0432\u0435\u0431-\u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B, \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u044B \u0438 \u0438\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u044F \u0432\u043D\u0443\u0442\u0440\u0438 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u043D\u0435\u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u044B\u043C\u0438.",
  "ui.settings.appearance.window_glass.coverage_full": "\u0412\u0441\u0451 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435",
  "ui.settings.appearance.window_glass.coverage_label": "\u0421\u0442\u0435\u043A\u043B\u043E \u043F\u0440\u0438\u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u043A",
  "ui.settings.appearance.window_glass.coverage_sidebars": "\u0422\u043E\u043B\u044C\u043A\u043E \u0431\u043E\u043A\u043E\u0432\u044B\u0435 \u043F\u0430\u043D\u0435\u043B\u0438",
  "ui.settings.appearance.window_glass.description": "\u041F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0440\u0430\u0431\u043E\u0447\u0435\u043C\u0443 \u0441\u0442\u043E\u043B\u0443 \u043F\u0440\u043E\u0441\u0432\u0435\u0447\u0438\u0432\u0430\u0442\u044C \u0441\u043A\u0432\u043E\u0437\u044C \u043E\u043A\u043D\u043E \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0441 \u0441\u0438\u0441\u0442\u0435\u043C\u043D\u044B\u043C \u0440\u0430\u0437\u043C\u044B\u0442\u0438\u0435\u043C. \u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u043E \u0432 macOS, \u0433\u0434\u0435 \u0441\u0438\u0441\u0442\u0435\u043C\u0430 \u044D\u0442\u043E \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442, \u0438 \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D\u043E \u0432 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445 \u0441\u043B\u0443\u0447\u0430\u044F\u0445. \u0422\u0435\u043A\u0441\u0442 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0447\u0438\u0442\u0430\u0435\u043C\u044B\u043C \u0432 \u043B\u044E\u0431\u043E\u0439 \u0442\u0435\u043C\u0435: \u043F\u043E\u043B\u0437\u0443\u043D\u043E\u043A \u043E\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0440\u0430\u043D\u044C\u0448\u0435, \u0447\u0435\u043C \u0442\u0435\u043A\u0441\u0442 \u0442\u0435\u043C\u044B \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u0442\u0440\u0443\u0434\u043D\u043E\u0447\u0438\u0442\u0430\u0435\u043C\u044B\u043C.",
  "ui.settings.appearance.window_glass.intensity_description": "\u0421\u043B\u0435\u0432\u0430 \u043C\u0430\u0442\u043E\u0432\u043E\u0435: \u0432 \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u043C \u043D\u0435\u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0435 \u0441 \u043B\u0451\u0433\u043A\u0438\u043C \u043D\u0430\u043C\u0451\u043A\u043E\u043C \u043D\u0430 \u0440\u0430\u0431\u043E\u0447\u0438\u0439 \u0441\u0442\u043E\u043B. \u0421\u043F\u0440\u0430\u0432\u0430 \u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0435 \u2014 \u043D\u0430\u0441\u0442\u043E\u043B\u044C\u043A\u043E, \u043D\u0430\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0447\u0438\u0442\u0430\u0435\u043C\u043E\u0441\u0442\u044C \u0442\u0435\u043A\u0441\u0442\u0430 \u0432 \u043A\u0430\u0436\u0434\u043E\u0439 \u0442\u0435\u043C\u0435. \u0411\u043B\u043E\u043A\u0438 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0439 \u0438 \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 \u043E\u0442\u0442\u0435\u043D\u043E\u043A \u0441\u0442\u0435\u043A\u043B\u0430, \u043F\u043E\u043B\u044F \u0432\u0432\u043E\u0434\u0430 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u043E\u0442\u043B\u0438\u0447\u043D\u044B\u043C\u0438 \u043E\u0442 \u0441\u0442\u0435\u043A\u043B\u0430, \u0430 \u043A\u043E\u0434, \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u044B \u0438 \u0438\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u044F \u2014 \u043D\u0435\u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u044B\u043C\u0438.",
  "ui.settings.appearance.window_glass.intensity_end": "\u041F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0435",
  "ui.settings.appearance.window_glass.intensity_label": "\u041E\u0442 \u043C\u0430\u0442\u043E\u0432\u043E\u0433\u043E \u0434\u043E \u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0433\u043E",
  "ui.settings.appearance.window_glass.intensity_start": "\u041C\u0430\u0442\u043E\u0432\u043E\u0435",
  "ui.settings.appearance.window_glass.intensity_value": "{value}% \u043A \u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0441\u0442\u0438",
  "ui.settings.appearance.window_glass.label": "\u041F\u043E\u043B\u0443\u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0435 \u043E\u043A\u043D\u043E",
  "ui.settings.appearance.window_glass.material_acrylic": "Acrylic",
  "ui.settings.appearance.window_glass.material_description": "\u0421\u0438\u0441\u0442\u0435\u043C\u043D\u044B\u0439 \u043C\u0430\u0442\u0435\u0440\u0438\u0430\u043B \u043F\u043E\u0434 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435\u043C. \u041E\u043D \u0442\u0430\u043A\u0436\u0435 \u0437\u0430\u0434\u0430\u0451\u0442 \u043F\u0440\u0435\u0434\u0435\u043B \u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0441\u0442\u0438.",
  "ui.settings.appearance.window_glass.material_label": "\u041C\u0430\u0442\u0435\u0440\u0438\u0430\u043B",
  "ui.settings.appearance.window_glass.material_menu": "\u041C\u0435\u043D\u044E",
  "ui.settings.appearance.window_glass.material_mica": "Mica",
  "ui.settings.appearance.window_glass.material_popover": "\u0412\u0441\u043F\u043B\u044B\u0432\u0430\u044E\u0449\u0435\u0435 \u043E\u043A\u043D\u043E",
  "ui.settings.appearance.window_glass.material_tabbed": "\u0412\u043A\u043B\u0430\u0434\u043A\u0438",
  "ui.settings.appearance.window_glass.material_window": "\u041E\u043A\u043D\u043E",
  "ui.settings.appearance.window_glass.restart_needed": "\u041F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 Local Operator, \u0447\u0442\u043E\u0431\u044B \u043F\u0440\u0438\u043C\u0435\u043D\u0438\u0442\u044C \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0435. \u0414\u043E \u044D\u0442\u043E\u0433\u043E \u043E\u043A\u043D\u043E \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442 \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0432\u0438\u0434.",
  "ui.settings.appearance.window_glass.unsupported_acceleration": "\u041F\u043E\u043B\u0443\u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0435 \u043E\u043A\u043D\u043E \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E, \u043F\u043E\u0442\u043E\u043C\u0443 \u0447\u0442\u043E \u0430\u043F\u043F\u0430\u0440\u0430\u0442\u043D\u043E\u0435 \u0443\u0441\u043A\u043E\u0440\u0435\u043D\u0438\u0435 \u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u043E \u0434\u043B\u044F \u044D\u0442\u043E\u0433\u043E \u0437\u0430\u043F\u0443\u0441\u043A\u0430 (--disable-gpu \u0438\u043B\u0438 \u043E\u0442\u043A\u0430\u0442 \u043F\u043E\u0441\u043B\u0435 \u0441\u0431\u043E\u044F). \u041F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 \u0441 \u0443\u0441\u043A\u043E\u0440\u0435\u043D\u0438\u0435\u043C, \u0447\u0442\u043E\u0431\u044B \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0435\u0433\u043E.",
  "ui.settings.appearance.window_glass.unsupported_backdrop_filter": "\u041F\u043E\u043B\u0443\u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0435 \u043E\u043A\u043D\u043E \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E, \u043F\u043E\u0442\u043E\u043C\u0443 \u0447\u0442\u043E \u044D\u0442\u043E\u0442 \u0440\u0435\u043D\u0434\u0435\u0440\u0435\u0440 \u043D\u0435 \u0443\u043C\u0435\u0435\u0442 \u0440\u0438\u0441\u043E\u0432\u0430\u0442\u044C \u0440\u0430\u0437\u043C\u044B\u0442\u0438\u0435 \u0444\u043E\u043D\u0430.",
  "ui.settings.appearance.window_glass.unsupported_gpu": "\u041F\u043E\u043B\u0443\u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0435 \u043E\u043A\u043D\u043E \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E, \u043F\u043E\u0442\u043E\u043C\u0443 \u0447\u0442\u043E GPU \u0441\u0435\u0439\u0447\u0430\u0441 \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u0435\u0433\u043E \u043A\u043E\u043C\u043F\u043E\u0437\u0438\u0442\u0438\u0440\u043E\u0432\u0430\u0442\u044C: \u043A\u043E\u043C\u043F\u043E\u0437\u0438\u0442\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0435 \u0438\u043B\u0438 \u0440\u0430\u0441\u0442\u0435\u0440\u0438\u0437\u0430\u0446\u0438\u044F \u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u044B \u043B\u0438\u0431\u043E \u0440\u0430\u0431\u043E\u0442\u0430\u044E\u0442 \u043F\u0440\u043E\u0433\u0440\u0430\u043C\u043C\u043D\u043E. \u041E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0434\u0440\u0430\u0439\u0432\u0435\u0440\u0430 \u0438\u043B\u0438 \u0432\u044B\u0445\u043E\u0434 \u0438\u0437 \u0443\u0434\u0430\u043B\u0451\u043D\u043D\u043E\u0439 \u0441\u0435\u0441\u0441\u0438\u0438 \u043C\u043E\u0433\u0443\u0442 \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440 \u0431\u0435\u0437 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u043A\u0430.",
  "ui.settings.appearance.window_glass.unsupported_linux": "\u041F\u043E\u043B\u0443\u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0435 \u043E\u043A\u043D\u043E \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E \u0432 Linux: \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u0437\u0430\u043F\u0440\u043E\u0441\u0438\u0442\u044C \u0432\u0441\u0442\u0440\u043E\u0435\u043D\u043D\u043E\u0435 \u0440\u0430\u0437\u043C\u044B\u0442\u0438\u0435 \u043E\u043A\u043D\u0430. \u041F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0441\u0442\u044C \u0440\u0430\u0431\u043E\u0447\u0435\u0433\u043E \u0441\u0442\u043E\u043B\u0430 \u0442\u0430\u043C \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u043A\u043E\u043C\u043F\u043E\u0437\u0438\u0442\u043E\u0440\u0430 (X11 \u0438\u043B\u0438 Wayland) \u0438 \u043C\u043E\u0436\u0435\u0442 \u043E\u0442\u043A\u0430\u0442\u0438\u0442\u044C\u0441\u044F \u043A \u043F\u0440\u043E\u0433\u0440\u0430\u043C\u043C\u043D\u043E\u043C\u0443 \u0440\u0430\u0437\u043C\u044B\u0442\u0438\u044E, \u0438\u0437-\u0437\u0430 \u0447\u0435\u0433\u043E \u0442\u0435\u043A\u0441\u0442 \u0440\u0430\u0431\u043E\u0447\u0435\u0433\u043E \u0441\u0442\u043E\u043B\u0430 \u0431\u0443\u0434\u0435\u0442 \u0432\u0438\u0434\u0435\u043D \u0441\u043A\u0432\u043E\u0437\u044C \u0442\u0435\u043A\u0441\u0442 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F.",
  "ui.settings.appearance.window_glass.unsupported_other": "\u041F\u043E\u043B\u0443\u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0435 \u043E\u043A\u043D\u043E \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E \u043D\u0430 \u044D\u0442\u043E\u0439 \u043F\u043B\u0430\u0442\u0444\u043E\u0440\u043C\u0435: \u043F\u0440\u043E\u0432\u0435\u0440\u0435\u043D\u043E \u0442\u043E\u043B\u044C\u043A\u043E \u043A\u043E\u043C\u043F\u043E\u0437\u0438\u0442\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0435 \u0440\u0430\u0437\u043C\u044B\u0442\u043E\u0433\u043E \u043E\u043A\u043D\u0430 \u0432 macOS, \u0430 \u043C\u0430\u0442\u0435\u0440\u0438\u0430\u043B Windows 11 \u0435\u0449\u0451 \u043D\u0435 \u043F\u0440\u043E\u0432\u0435\u0440\u0435\u043D \u043D\u0430 \u0440\u0435\u0430\u043B\u044C\u043D\u043E\u0439 \u043C\u0430\u0448\u0438\u043D\u0435.",
  "ui.settings.appearance.window_glass.unsupported_reduced_transparency": "\u041F\u043E\u043B\u0443\u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0435 \u043E\u043A\u043D\u043E \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E, \u043F\u043E\u0442\u043E\u043C\u0443 \u0447\u0442\u043E \u0432 \u0441\u0438\u0441\u0442\u0435\u043C\u043D\u044B\u0445 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u043F\u0435\u0446\u0438\u0430\u043B\u044C\u043D\u044B\u0445 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u0435\u0439 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u043E \xAB\u0423\u043C\u0435\u043D\u044C\u0448\u0435\u043D\u0438\u0435 \u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0441\u0442\u0438\xBB. \u041E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u0435 \u0435\u0451 \u0442\u0430\u043C, \u0447\u0442\u043E\u0431\u044B \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u044D\u0442\u043E\u0442 \u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440.",
  "ui.settings.appearance.window_glass.unsupported_windows_too_old": "\u0414\u043B\u044F \u043F\u043E\u043B\u0443\u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0433\u043E \u043E\u043A\u043D\u0430 \u043D\u0443\u0436\u043D\u0430 Windows 11 \u0432\u0435\u0440\u0441\u0438\u0438 22H2 \u0438\u043B\u0438 \u043D\u043E\u0432\u0435\u0435.",
  "ui.settings.appearance.window_glass.unsupported_windows_unverified": "\u041F\u043E\u043B\u0443\u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u043E\u0435 \u043E\u043A\u043D\u043E \u043F\u043E\u043A\u0430 \u043D\u0435 \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442\u0441\u044F \u0432 Windows: Mica \u0438 Acrylic \u0440\u0435\u0430\u043B\u0438\u0437\u043E\u0432\u0430\u043D\u044B, \u043D\u043E \u043D\u0435 \u043F\u0440\u043E\u0432\u0435\u0440\u0435\u043D\u044B \u043D\u0430 \u0440\u0435\u0430\u043B\u044C\u043D\u043E\u0439 \u043C\u0430\u0448\u0438\u043D\u0435 \u0441 Windows, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D\u043D\u044B\u043C \u0434\u043E \u0442\u0430\u043A\u043E\u0439 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0438."
};

