  "ui.settings.integrations.mcp_management_section.retry": "\u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u044C",
  "ui.settings.integrations.mcp_management_section.search_integrations": "\u041F\u043E\u0438\u0441\u043A \u0438\u043D\u0442\u0435\u0433\u0440\u0430\u0446\u0438\u0439",
  "ui.settings.integrations.mcp_management_section.search_integrations_placeholder": "\u041F\u043E\u0438\u0441\u043A {integrations}",
