  "ui.settings.model.settings_page.configure_the_default_ai_model_and_hosting_providers_used_for_gen": "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u0442\u0435 \u043C\u043E\u0434\u0435\u043B\u044C \u0418\u0418 \u0438 \u043F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440\u043E\u0432 \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0434\u043B\u044F \u0433\u0435\u043D\u0435\u0440\u0430\u0446\u0438\u0438 \u043E\u0442\u0432\u0435\u0442\u043E\u0432. \u041E\u043D\u0438 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442\u0441\u044F \u0432\u0441\u0435\u043C\u0438 \u0430\u0433\u0435\u043D\u0442\u0430\u043C\u0438 \u0431\u0435\u0437 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0439 \u043C\u043E\u0434\u0435\u043B\u0438 \u0438\u043B\u0438 \u043F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440\u0430. \u0414\u043B\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0445 \u0430\u0433\u0435\u043D\u0442\u043E\u0432 \u044D\u0442\u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u043C\u043E\u0436\u043D\u043E \u043F\u0435\u0440\u0435\u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u0442\u044C.",
  "ui.settings.model.settings_page.model_providers": "\u041F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440\u044B \u043C\u043E\u0434\u0435\u043B\u0435\u0439",
  "ui.settings.model.settings_page.model_settings": "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u043C\u043E\u0434\u0435\u043B\u0438",
  "ui.settings.model.settings_page.no_hosting_options": "\u041D\u0435\u0442 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0445 \u043F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440\u043E\u0432. \u0412\u043E\u0439\u0434\u0438\u0442\u0435 \u043A \u043F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440\u0443 \u0438\u043B\u0438 \u0434\u043E\u0431\u0430\u0432\u044C\u0442\u0435 \u0435\u0433\u043E \u043A\u043B\u044E\u0447 API \u043D\u0438\u0436\u0435, \u0432 \u0440\u0430\u0437\u0434\u0435\u043B\u0435 \xAB\u041F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440\u044B\xBB.",
  "ui.settings.model.settings_page.you_need_a_radient_account_or_your_own_api_keys_to_reach_cloud_pr": "\u0414\u043B\u044F \u043E\u0431\u043B\u0430\u0447\u043D\u044B\u0445 \u043F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440\u043E\u0432 \u043D\u0443\u0436\u043D\u0430 \u0443\u0447\u0451\u0442\u043D\u0430\u044F \u0437\u0430\u043F\u0438\u0441\u044C Radient \u0438\u043B\u0438 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0435 \u043A\u043B\u044E\u0447\u0438 API. \u0415\u0441\u043B\u0438 \u043F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440\u043E\u0432 \u0438 \u043C\u043E\u0434\u0435\u043B\u0435\u0439 \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0435\u0442, \u0432\u043E\u0439\u0434\u0438\u0442\u0435 \u0432 Radient \u0438\u043B\u0438 \u0434\u043E\u0431\u0430\u0432\u044C\u0442\u0435 \u043A\u043B\u044E\u0447 \u043F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440\u0430 \u043D\u0438\u0436\u0435, \u0432 \u0440\u0430\u0437\u0434\u0435\u043B\u0435 \xAB\u041F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440\u044B\xBB.",
  "ui.settings.model.system_prompt.cancel": "\u041E\u0442\u043C\u0435\u043D\u0430",
  "ui.settings.model.system_prompt.enter_instructions_for_how_all_agents_should_behave_and_respond_t": "\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u0438\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0438\u0438 \u043E \u0442\u043E\u043C, \u043A\u0430\u043A \u0432\u0441\u0435 \u0430\u0433\u0435\u043D\u0442\u044B \u0434\u043E\u043B\u0436\u043D\u044B \u0432\u0435\u0441\u0442\u0438 \u0441\u0435\u0431\u044F \u0438 \u043E\u0442\u0432\u0435\u0447\u0430\u0442\u044C \u043D\u0430 \u0432\u0430\u0448\u0438 \u0437\u0430\u043F\u0440\u043E\u0441\u044B\u2026",
