  "ui.agentMessages.dialog.later": "\u0622\u067E \u0627\u0633\u06D2 \u0628\u0639\u062F \u0645\u06CC\u06BA \u062A\u0631\u062A\u06CC\u0628\u0627\u062A \u2192 \u0627\u06CC\u062C\u0646\u0679 \u067E\u06CC\u063A\u0627\u0645\u0627\u062A \u0645\u06CC\u06BA \u0641\u0639\u0627\u0644 \u06A9\u0631 \u0633\u06A9\u062A\u06D2 \u06C1\u06CC\u06BA\u06D4",
