  "ui.onboarding.default_model.block.loading_models": "\u0645\u0627\u0688\u0644\u0632 \u06A9\u06CC \u0641\u06C1\u0631\u0633\u062A \u0644\u0648\u0688 \u06C1\u0648 \u0631\u06C1\u06CC \u06C1\u06D2\u2026",
