  "ui.onboarding.default_model.empty_helper": "\u0627\u0628\u06BE\u06CC \u06A9\u0648\u0626\u06CC \u0641\u0631\u0627\u06C1\u0645 \u06A9\u0646\u0646\u062F\u06C1 \u0645\u0646\u0633\u0644\u06A9 \u0646\u06C1\u06CC\u06BA\u06D4 \u0627\u06CC\u06A9 \u0642\u062F\u0645 \u0648\u0627\u067E\u0633 \u062C\u0627 \u06A9\u0631 \u0645\u0646\u0633\u0644\u06A9 \u06A9\u0631\u06CC\u06BA\u06D4",
