  "ui.settings.appearance.window_glass.unsupported_other": "\u0627\u0633 \u067E\u0644\u06CC\u0679 \u0641\u0627\u0631\u0645 \u067E\u0631 \u0646\u06CC\u0645 \u0634\u0641\u0627\u0641 \u0648\u0646\u0688\u0648 \u062F\u0633\u062A\u06CC\u0627\u0628 \u0646\u06C1\u06CC\u06BA\u061B \u0635\u0631\u0641 macOS \u067E\u0631 \u062F\u06BE\u0646\u062F\u0644\u06CC \u0648\u0646\u0688\u0648 \u06A9\u06CC \u0622\u0645\u06CC\u0632\u0634 \u062A\u0635\u062F\u06CC\u0642 \u0634\u062F\u06C1 \u06C1\u06D2\u060C \u0627\u0648\u0631 Windows 11 \u06A9\u0627 \u0645\u0679\u06CC\u0631\u06CC\u0644 \u0627\u0628\u06BE\u06CC \u062D\u0642\u06CC\u0642\u06CC \u0645\u0634\u06CC\u0646 \u067E\u0631 \u062A\u0635\u062F\u06CC\u0642 \u0634\u062F\u06C1 \u0646\u06C1\u06CC\u06BA\u06D4",
