  "ui.settings.appearance.window_glass.coverage_description": "\u0648\u0646\u0688\u0648 \u06A9\u06D2 \u06A9\u0648\u0646 \u0633\u06D2 \u062D\u0635\u06D2 \u0646\u06CC\u0645 \u0634\u0641\u0627\u0641 \u06C1\u0648\u06BA\u06D4 \u0635\u0631\u0641 \u0633\u0627\u0626\u06CC\u0688 \u0628\u0627\u0631\u0632 \u06AF\u0641\u062A\u06AF\u0648 \u0627\u0648\u0631 \u0635\u0641\u062D\u0627\u062A \u06A9\u0648 \u063A\u06CC\u0631 \u0634\u0641\u0627\u0641 \u0631\u06A9\u06BE\u062A\u0627 \u06C1\u06D2\u06D4 \u067E\u0648\u0631\u06CC \u0627\u06CC\u067E \u0627\u0646 \u067E\u0631 \u0627\u0648\u0631 \u0633\u0627\u0626\u06CC\u0688 \u067E\u06CC\u0646\u0644\u0632 \u067E\u0631 \u0628\u06BE\u06CC \u0627\u062B\u0631 \u0688\u0627\u0644\u062A\u0627 \u06C1\u06D2\u061B \u0627\u0646\u062F\u0631 \u062F\u06A9\u06BE\u0627\u0626\u06D2 \u06AF\u0626\u06D2 \u0648\u06CC\u0628 \u0635\u0641\u062D\u0627\u062A\u060C \u062F\u0633\u062A\u0627\u0648\u06CC\u0632\u0627\u062A \u0627\u0648\u0631 \u062A\u0635\u0627\u0648\u06CC\u0631 \u063A\u06CC\u0631 \u0634\u0641\u0627\u0641 \u0631\u06C1\u062A\u06D2 \u06C1\u06CC\u06BA\u06D4",
  "ui.settings.appearance.window_glass.coverage_sidebars": "\u0635\u0631\u0641 \u0633\u0627\u0626\u06CC\u0688 \u0628\u0627\u0631\u0632",
