  "ui.settings.appearance.window_glass.material_label": "\u0645\u0679\u06CC\u0631\u06CC\u0644",
  "ui.settings.appearance.window_glass.material_description": "\u0627\u06CC\u067E \u06A9\u06D2 \u067E\u06CC\u0686\u06BE\u06D2 \u0633\u0633\u0679\u0645 \u06A9\u0627 \u0645\u0679\u06CC\u0631\u06CC\u0644\u06D4 \u06CC\u06C1 \u0634\u0641\u0627\u0641\u06CC\u062A \u06A9\u06CC \u062D\u062F \u0628\u06BE\u06CC \u0645\u0642\u0631\u0631 \u06A9\u0631\u062A\u0627 \u06C1\u06D2\u06D4",
