  "ui.settings.language.general.system": "\u0633\u0633\u0679\u0645 \u06A9\u06CC \u0632\u0628\u0627\u0646 \u0627\u0633\u062A\u0639\u0645\u0627\u0644 \u06A9\u0631\u06CC\u06BA",
  "ui.settings.language.general.unavailable_choice": "\u062F\u0633\u062A\u06CC\u0627\u0628 \u0646\u06C1\u06CC\u06BA",
  "ui.settings.language.general.write_error": "\u0632\u0628\u0627\u0646 \u0645\u062D\u0641\u0648\u0638 \u0646\u06C1\u06CC\u06BA \u06C1\u0648\u0626\u06CC\u06D4 \u0622\u067E \u06A9\u06CC \u067E\u0686\u06BE\u0644\u06CC \u062A\u0631\u062A\u06CC\u0628 \u0628\u0631\u0642\u0631\u0627\u0631 \u06C1\u06D2\u06D4 {message}",
