  "ui.settings.page.title": "\u062A\u0631\u062A\u06CC\u0628\u0627\u062A",
  "ui.settings.profile.description_anonymous": "\u0627\u06CC\u067E \u0645\u06CC\u06BA \u062F\u06A9\u06BE\u0627\u0626\u06CC \u062C\u0627\u0646\u06D2 \u0648\u0627\u0644\u06CC \u0622\u067E \u06A9\u06CC \u0635\u0627\u0631\u0641 \u067E\u0631\u0648\u0641\u0627\u0626\u0644 \u06A9\u06CC \u0645\u0639\u0644\u0648\u0645\u0627\u062A\u06D4 \u06CC\u06C1 \u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0627\u06CC\u062C\u0646\u0679\u0633 \u06A9\u0648 \u0646\u06C1\u06CC\u06BA \u062F\u06CC \u062C\u0627\u062A\u06CC\u06BA\u06D4",
  "ui.settings.profile.description_authenticated": "\u0627\u06CC\u067E \u0645\u06CC\u06BA \u062F\u06A9\u06BE\u0627\u0626\u06CC \u062C\u0627\u0646\u06D2 \u0648\u0627\u0644\u06CC \u0622\u067E \u06A9\u06CC \u0635\u0627\u0631\u0641 \u067E\u0631\u0648\u0641\u0627\u0626\u0644 \u06A9\u06CC \u0645\u0639\u0644\u0648\u0645\u0627\u062A\u06D4 \u06CC\u06C1 \u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0627\u06CC\u062C\u0646\u0679\u0633 \u06A9\u0648 \u0646\u06C1\u06CC\u06BA \u062F\u06CC \u062C\u0627\u062A\u06CC\u06BA\u06D4 \u06CC\u06C1 \u062A\u0641\u0635\u06CC\u0644\u0627\u062A \u0622\u067E \u06A9\u06D2 Radient \u0627\u06A9\u0627\u0624\u0646\u0679 \u0633\u06D2 \u0641\u0631\u0627\u06C1\u0645 \u06A9\u06CC \u062C\u0627\u062A\u06CC \u06C1\u06CC\u06BA\u06D4",
