  "ui.settings.profile.email.placeholder": "\u0627\u067E\u0646\u0627 \u0627\u06CC \u0645\u06CC\u0644 \u062F\u0631\u062C \u06A9\u0631\u06CC\u06BA\u2026",
  "ui.settings.profile.title": "\u0635\u0627\u0631\u0641 \u067E\u0631\u0648\u0641\u0627\u0626\u0644",
  "ui.settings.section.interface_language.help": "\u0627\u0646\u0679\u0631\u0641\u06CC\u0633 \u06A9\u06CC \u0632\u0628\u0627\u0646\u060C \u0679\u0631\u0645\u06CC\u0646\u0644 \u06A9\u06D2 \u0633\u0627\u062A\u06BE \u0645\u0634\u062A\u0631\u06A9\u06C1 \u062A\u0631\u062A\u06CC\u0628\u06D4 auto \u0622\u067E \u06A9\u06D2 \u0622\u067E\u0631\u06CC\u0679\u0646\u06AF \u0633\u0633\u0679\u0645 \u06A9\u06CC \u0632\u0628\u0627\u0646 \u0627\u067E\u0646\u0627\u062A\u0627 \u06C1\u06D2\u060C \u0648\u0631\u0646\u06C1 \u0627\u0646\u06AF\u0631\u06CC\u0632\u06CC \u0627\u0633\u062A\u0639\u0645\u0627\u0644 \u06C1\u0648\u062A\u06CC \u06C1\u06D2\u06D4",
