  "ui.settings.tour.title": "\u0627\u06CC\u067E \u06A9\u0627 \u062A\u0639\u0627\u0631\u0641\u06CC \u062F\u0648\u0631\u06C1",
  "ui.settings.profile.account_checking": "\u0622\u067E \u06A9\u0627 Radient \u0627\u06A9\u0627\u0624\u0646\u0679 \u062C\u0627\u0646\u0686\u0627 \u062C\u0627 \u0631\u06C1\u0627 \u06C1\u06D2\u2026",
  "ui.settings.profile.account_read_failed_retry": "\u0622\u067E \u06A9\u0627 Radient \u0627\u06A9\u0627\u0624\u0646\u0679 \u067E\u0691\u06BE\u0627 \u0646\u06C1\u06CC\u06BA \u062C\u0627 \u0633\u06A9\u0627\u060C \u0627\u0633 \u0644\u06CC\u06D2 \u0646\u06CC\u0686\u06D2 \u0646\u0627\u0645 \u0627\u0648\u0631 \u0627\u06CC \u0645\u06CC\u0644 \u0622\u067E \u06A9\u06D2 \u0627\u06A9\u0627\u0624\u0646\u0679 \u06A9\u06CC \u062A\u0641\u0635\u06CC\u0644\u0627\u062A \u0646\u06C1\u06CC\u06BA \u0628\u0644\u06A9\u06C1 \u0639\u0627\u0631\u0636\u06CC \u0646\u0645\u0648\u0646\u06D2 \u06C1\u06CC\u06BA\u06D4 \u062F\u0648\u0628\u0627\u0631\u06C1 \u06A9\u0648\u0634\u0634 \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.settings.profile.account_read_failed_refused": "\u0622\u067E \u06A9\u0627 Radient \u0627\u06A9\u0627\u0624\u0646\u0679 \u067E\u0691\u06BE\u0627 \u0646\u06C1\u06CC\u06BA \u062C\u0627 \u0633\u06A9\u0627\u060C \u0627\u0633 \u0644\u06CC\u06D2 \u0646\u06CC\u0686\u06D2 \u0646\u0627\u0645 \u0627\u0648\u0631 \u0627\u06CC \u0645\u06CC\u0644 \u0622\u067E \u06A9\u06D2 \u0627\u06A9\u0627\u0624\u0646\u0679 \u06A9\u06CC \u062A\u0641\u0635\u06CC\u0644\u0627\u062A \u0646\u06C1\u06CC\u06BA \u0628\u0644\u06A9\u06C1 \u0639\u0627\u0631\u0636\u06CC \u0646\u0645\u0648\u0646\u06D2 \u06C1\u06CC\u06BA\u06D4 \u062F\u0648\u0628\u0627\u0631\u06C1 \u06A9\u0648\u0634\u0634 \u06A9\u0631\u06CC\u06BA \u06CC\u0627 Radient \u0645\u06CC\u06BA \u062F\u0648\u0628\u0627\u0631\u06C1 \u0633\u0627\u0626\u0646 \u0627\u0646 \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.settings.profile.retry": "\u062F\u0648\u0628\u0627\u0631\u06C1 \u06A9\u0648\u0634\u0634 \u06A9\u0631\u06CC\u06BA",
