    hairlineStrong: "#B3B5BE",
    // Derived. The old theme bounded inputs at 15 percent black, about 1.4:1.
    borderControl: "#787D97",
    accent: "#2D539E",
    accentHover: "#1E3A7D",
    accentActive: "#162E63",
    // The chart's hover mark, a step AWAY from the plot ground rather than along the
